    slug: "pay-per-lead-personal-injury-leads",
    title: "Pay-Per-Lead Personal Injury Leads: The Basics Explained",
    metaTitle: "Pay-Per-Lead Personal Injury Leads Explained",
    excerpt: "A foundational explanation of what pay-per-lead personal injury leads are and how they work.",
    metaDescription: "A foundational explanation of what pay-per-lead personal injury leads are, how pricing works, and what separates a qualified lead from a wasted contact.",
    category: "Personal Injury",
    readTime: "7 min read",
    publishedDate: "2026-10-25",
